/* PacketPath: Zona 3 "Trunks y VLAN nativa".
   Práctica primero: dos lecciones cortas con simulador visual, un lab guiado, una lección de leer "show",
   un troubleshooting, un lab a ciegas y la certificación con lab. Edita aquí textos y preguntas. */
Object.assign(LES,{
't31':{id:'t3-1',lv:3,t:'El trunk por dentro: la etiqueta 802.1Q',
 story:'Beto Ruiz, del NOC, te enseña el uplink del tercer piso: "Por este cable pasan Ventas, RRHH, cámaras, voz y el Wi-Fi de invitados. Un solo cable, cinco redes. ¿Cómo sabe el core de quién es cada frame?" Hoy lo descubres.',
 body:['En la Zona 1 hiciste un trunk con una sola VLAN. En un edificio real, el cable que sube de cada piso al core lleva <strong>muchas VLAN al mismo tiempo</strong>: datos, voz, cámaras, invitados. El switch de enfrente necesita saber a qué VLAN pertenece cada frame. Para eso existe la <strong>etiqueta 802.1Q</strong>.',
  '<h3>La etiqueta: 4 bytes dentro del frame</h3>Cuando un frame sale por un trunk, el switch le inserta 4 bytes entre la MAC origen y el EtherType. Lo más importante ahí es el <strong>VLAN ID</strong>: 12 bits, de 1 a 4094. También trae 3 bits de <strong>prioridad</strong> (los usa la voz para pasar primero). El switch que recibe lee el VLAN ID, quita la etiqueta y entrega el frame solo a los puertos de esa VLAN.',
  '<h3>Access y trunk, frente a frente</h3><ul class="pasos"><li><strong>Access port:</strong> una sola VLAN, frames <em>sin</em> etiqueta. Es donde van las PCs, impresoras y cámaras. Ellas nunca ven la etiqueta.</li><li><strong>Trunk:</strong> varias VLAN, cada frame <em>con</em> su etiqueta. Es el cable entre switches, o hacia un AP o un servidor de virtualización.</li></ul>',
  '<h3>La lista de VLAN permitidas: poda el trunk</h3>Un trunk solo lleva las VLAN de su <strong>lista de permitidas</strong>. Aquí los fabricantes cambian, y esto causa muchos tickets:<ul class="pasos"><li><strong>Cisco IOS</strong> permite <em>todas</em> por defecto (1-4094). Si no escribes la lista, todo pasa.</li><li><strong>Aruba AOS-CX</strong> y <strong>Juniper</strong> solo llevan las que tú agregas.</li></ul>La buena práctica es <strong>podar</strong>: dejar pasar solo las VLAN que ese piso necesita. Menos broadcast viajando de más y menos superficie de ataque: la VLAN de servidores no tiene nada que hacer en el switch de la recepción.',
  'Juega abajo: arma el trunk y manda frames de cada VLAN.'],
 fig:'trunk1',
 real:'<h3>Así lo ves en la vida real</h3><p>Cuando alguien dice "la VLAN de cámaras no llega al cuarto piso", lo primero que escribe un ingeniero en el switch de ese piso es <code>show interfaces trunk</code> (Cisco), <code>show interface brief</code> (Aruba) o <code>show ethernet-switching interfaces</code> (Juniper). En nueve de cada diez casos la VLAN no está en la lista de permitidas de algún extremo, o no existe en ese switch.</p>',
 quiz:[{q:'¿Qué agrega 802.1Q a un frame que sale por un trunk?',o:['Una etiqueta con el VLAN ID','Una dirección IP','Una contraseña','Una MAC nueva'],a:0,why:'Inserta una etiqueta de 4 bytes; lo esencial es el VLAN ID de 12 bits.'},
  {q:'¿Cuántos bits tiene el VLAN ID?',o:['8','12','16','32'],a:1,why:'12 bits: por eso las VLAN van de 1 a 4094.'},
  {q:'¿Una PC conectada a un access port ve la etiqueta 802.1Q?',o:['Sí, siempre','No, el switch se la quita antes de entregar','Solo si es Windows','Solo en la VLAN 1'],a:1,why:'El access port entrega los frames sin etiqueta.'},
  {q:'¿Dónde se usa normalmente un trunk?',o:['Entre switches, o hacia un AP o un servidor con varias VLAN','Hacia cada PC','Solo en el router de internet','En el cable de la impresora'],a:0,why:'El trunk lleva varias VLAN por el mismo cable.'},
  {q:'En Cisco IOS, si no configuras la lista de VLAN permitidas, el trunk…',o:['No deja pasar ninguna','Deja pasar todas (1-4094)','Solo deja pasar la VLAN 1','Se apaga'],a:1,why:'Cisco permite todas por defecto; por eso hay que podar.'},
  {q:'En Aruba AOS-CX, ¿qué VLAN lleva un trunk recién configurado?',o:['Todas','Solo las que agregas con vlan trunk allowed','Ninguna nunca','La 1 y la 999'],a:1,why:'Aruba solo lleva las que tú agregas a la lista.'},
  {q:'¿Qué es "podar" un trunk?',o:['Cortar el cable','Dejar pasar solo las VLAN que se necesitan en ese enlace','Borrar todas las VLAN','Cambiar la velocidad'],a:1,why:'Podar es recortar la lista de permitidas.'},
  {q:'La VLAN 30 existe en los dos switches, pero no cruza el trunk. ¿Qué revisas primero?',o:['Que esté en la lista de permitidas en los dos extremos','La IP de las PCs','El color del cable','El DNS'],a:0,why:'Si un extremo no la permite, no cruza.'},
  {q:'¿Para qué sirven los 3 bits de prioridad de la etiqueta?',o:['Para que el tráfico de voz pase primero (QoS)','Para elegir la VLAN','Para cifrar','Para el número de puerto'],a:0,why:'Son la prioridad 802.1p, que usa QoS.'},
  {q:'¿Por qué es buena idea podar el trunk hacia el switch de la recepción?',o:['Para que no lleguen ahí VLAN que no se usan, como la de servidores','Para que el cable dure más','Porque Juniper lo exige','No es buena idea'],a:0,why:'Menos broadcast de más y menos superficie de ataque.'}],
 exp:{q:'Con tus palabras: ¿cómo sabe el switch de enfrente a qué VLAN pertenece cada frame de un trunk, y por qué conviene podar la lista de VLAN permitidas?',
  ideas:['Al salir por el trunk, el frame lleva una etiqueta 802.1Q con el VLAN ID','El switch que recibe lee la etiqueta, la quita y lo entrega solo en esa VLAN','El trunk solo lleva las VLAN de su lista de permitidas (Cisco permite todas por defecto)','Podar deja pasar solo las VLAN necesarias: menos broadcast y más seguridad'],
  short:['la etiqueta 802.1Q','qué hace el que recibe','la lista de permitidas','por qué podar'],
  kw:[['802.1q','etiqueta','tag','vlan id'],['quita','lee','entrega','recibe'],['permitid','allowed','lista','todas'],['poda','segur','broadcast','solo las']],
  fix:['Al salir por el trunk, cada frame lleva una etiqueta 802.1Q con su VLAN ID.','El switch que lo recibe lee la etiqueta, la quita y entrega el frame solo en esa VLAN.','El trunk solo lleva las VLAN de su lista de permitidas; Cisco permite todas por defecto.','Podar deja pasar solo las VLAN que se necesitan: menos broadcast y más seguridad.'],
  mine:'Por el trunk viajan varias VLAN en el mismo cable, así que cada frame sale con una etiqueta 802.1Q que trae el número de VLAN. El switch de enfrente lee esa etiqueta, la quita y entrega el frame solo a los puertos de esa VLAN; la PC nunca ve la etiqueta. El trunk solo lleva las VLAN de su lista de permitidas: en Cisco por defecto pasan todas, en Aruba y Juniper solo las que agregas. Conviene podar y dejar solo las que ese piso usa, para que no viaje broadcast de más y para que una VLAN como la de servidores no llegue a donde no debe.',
  model:'Cada frame del trunk lleva una etiqueta 802.1Q con su VLAN ID; el switch que recibe la lee, la quita y lo entrega en esa VLAN. El trunk solo lleva las VLAN permitidas (Cisco: todas por defecto). Podar = dejar solo las necesarias: menos broadcast y más seguridad.'}},
't32':{id:'t3-2',lv:3,t:'VLAN nativa: la que viaja sin etiqueta',
 story:'El log del core amaneció lleno de <code>%CDP-4-NATIVE_VLAN_MISMATCH</code> y las cámaras del piso 2 no se ven. Pepe Toño jura que "solo cambió un parámetro" en el trunk. Lupita: "Explícale a Pepe Toño qué es la nativa antes de que toque otro switch."',
 body:['En todo trunk 802.1Q hay una VLAN especial: la <strong>VLAN nativa</strong>. Sus frames son los únicos que viajan <strong>sin etiqueta</strong>. Si al switch le llega un frame sin etiqueta por un trunk, lo mete en su VLAN nativa. Si no cambias nada, la nativa es la <strong>VLAN 1</strong> en Cisco, Aruba y Juniper.',
  '<h3>La regla: la misma nativa en los dos extremos</h3>Imagina que SW1 tiene nativa 10 y SW2 tiene nativa 1. SW1 manda los frames de la VLAN 10 <em>sin</em> etiqueta. SW2 los recibe sin etiqueta y los mete en <em>su</em> nativa: la VLAN 1. Resultado: <strong>la VLAN 10 se rompe en ese enlace</strong>, y además su tráfico se mezcla con otra VLAN, que es un problema de seguridad.',
  '<h3>La buena práctica: una nativa dedicada que nadie usa</h3><ul class="pasos"><li><strong>Crea una VLAN solo para ser nativa</strong>, sin PCs: por ejemplo la <strong>999 NATIVA</strong>.</li><li><strong>Ponla como nativa en los dos extremos</strong> de cada trunk.</li><li><strong>No uses la VLAN 1</strong> para usuarios ni como nativa: es la que tienen todos los puertos por defecto y la que usan ataques como el <em>VLAN hopping</em> por doble etiqueta.</li></ul>',
  '<h3>Cómo se configura y cómo te enteras</h3><ul class="pasos"><li><strong>Cisco:</strong> <code>switchport trunk native vlan 999</code>. Si el vecino también es Cisco, CDP te avisa con <code>%CDP-4-NATIVE_VLAN_MISMATCH</code>.</li><li><strong>Aruba:</strong> <code>vlan trunk native 999</code>. No hay aviso: lo ves en <code>show interface brief</code>, columna Native VLAN.</li><li><strong>Juniper:</strong> <code>set interfaces ge-0/0/23 native-vlan-id 999</code>. Lo ves en <code>show ethernet-switching interfaces</code>: la nativa sale como <em>untagged</em>.</li></ul>Con vendors mezclados nadie te avisa: tienes que comparar los dos extremos tú.',
  'Juega abajo: rompe y arregla la nativa.'],
 fig:'trunk2',
 real:'<h3>Así lo ves en la vida real</h3><p>Los auditores de seguridad revisan dos cosas en cada trunk: que no lleve VLAN de más y que la nativa no sea la 1. Por eso en casi todas las empresas verás una VLAN como la 999 o la 666 llamada NATIVA o BLACKHOLE, sin un solo puerto. Y cuando "una VLAN cruza un piso pero no otro", la nativa distinta en un extremo es de las primeras sospechosas.</p>',
 quiz:[{q:'¿Qué tienen de especial los frames de la VLAN nativa en un trunk?',o:['Viajan sin etiqueta','Viajan cifrados','Viajan dos veces','Van más rápido'],a:0,why:'La nativa es la única VLAN que viaja sin etiqueta 802.1Q.'},
  {q:'Si no configuras nada, ¿cuál es la VLAN nativa?',o:['VLAN 1','VLAN 999','La VLAN más alta','No hay nativa'],a:0,why:'Por defecto es la VLAN 1 en los tres fabricantes.'},
  {q:'SW1 tiene nativa 10 y SW2 nativa 1. ¿Qué pasa con la VLAN 10 en ese enlace?',o:['Funciona igual','SW1 la manda sin etiqueta y SW2 la mete en la VLAN 1: se rompe','Se cifra','Se duplica'],a:1,why:'Lo que llega sin etiqueta va a la nativa del que recibe.'},
  {q:'¿Cuál es la buena práctica para la VLAN nativa?',o:['Usar la VLAN 1','Usar una VLAN dedicada sin puertos, como la 999, igual en los dos extremos','Usar la VLAN de Ventas','Cambiarla cada semana'],a:1,why:'Una nativa dedicada y sin uso evita mezclas y ataques.'},
  {q:'¿Qué mensaje muestra un Cisco cuando la nativa no coincide con otro Cisco?',o:['%CDP-4-NATIVE_VLAN_MISMATCH','%LINK-3-UPDOWN','%SYS-5-CONFIG_I','%DHCP-6-ADDRESS_ASSIGN'],a:0,why:'CDP compara la nativa con el vecino Cisco y avisa.'},
  {q:'Con un Aruba y un Juniper en los extremos del trunk, ¿quién te avisa si la nativa no coincide?',o:['Nadie: hay que comparar los dos extremos','CDP','El DHCP','La PC'],a:0,why:'CDP es de Cisco; con otros vendors no hay aviso automático.'},
  {q:'Aruba AOS-CX: ¿cómo pones la nativa 999 en un trunk?',o:['vlan trunk native 999','switchport trunk native vlan 999','set native 999','native-vlan-id 999'],a:0,why:'En AOS-CX es vlan trunk native.'},
  {q:'Juniper Junos: ¿cómo pones la nativa 999 en ge-0/0/23?',o:['set interfaces ge-0/0/23 native-vlan-id 999','vlan trunk native 999','switchport trunk native vlan 999','set vlans NATIVA native'],a:0,why:'En Junos (ELS) va a nivel de interfaz: native-vlan-id.'},
  {q:'¿Por qué no se recomienda usar la VLAN 1 como nativa?',o:['Porque todos los puertos están ahí por defecto y la aprovechan ataques como el VLAN hopping','Porque es lenta','Porque no existe en Aruba','Porque es la de voz'],a:0,why:'La VLAN 1 es el blanco más común.'},
  {q:'¿La VLAN nativa dedicada (999) necesita PCs conectadas?',o:['No, existe solo para ser la nativa','Sí, al menos una','Sí, el servidor DHCP','Solo en Cisco'],a:0,why:'Se deja vacía a propósito.'}],
 exp:{q:'Con tus palabras: ¿qué es la VLAN nativa, qué pasa si no coincide en los dos extremos y cuál es la buena práctica?',
  ideas:['La nativa es la VLAN que viaja sin etiqueta por el trunk (por defecto la 1)','Lo que llega sin etiqueta, el switch lo mete en su propia nativa','Si no coincide, esa VLAN se rompe o se mezcla con otra en ese enlace','Buena práctica: una VLAN dedicada sin uso (como la 999), igual en ambos extremos, y no la VLAN 1'],
  short:['qué es la nativa','qué hace el que recibe','si no coincide','la buena práctica'],
  kw:[['sin etiqueta','sin tag','untagged','nativa'],['recibe','mete','su nativa','llega'],['no coincid','mismatch','rompe','mezcla','distinta'],['999','dedicada','vlan 1','sin uso','igual']],
  fix:['La VLAN nativa es la única que viaja sin etiqueta por el trunk; por defecto es la VLAN 1.','Lo que llega sin etiqueta, el switch lo mete en su propia VLAN nativa.','Si la nativa no coincide, esa VLAN se rompe en el enlace o su tráfico se mezcla con otra.','La buena práctica es una VLAN dedicada sin puertos, como la 999, igual en los dos extremos, y no usar la 1.'],
  mine:'En un trunk todas las VLAN viajan con etiqueta menos una: la nativa, que por defecto es la VLAN 1. Cuando a un switch le llega un frame sin etiqueta por el trunk, lo mete en su nativa. Si de un lado la nativa es la 10 y del otro la 1, los frames de la 10 salen sin etiqueta y del otro lado caen en la VLAN 1: la 10 deja de funcionar en ese enlace y además se mezcla con otra VLAN. Por eso se crea una VLAN que nadie usa, como la 999 NATIVA, y se pone igual en los dos extremos de cada trunk, y no se usa la VLAN 1.',
  model:'La nativa viaja sin etiqueta (por defecto VLAN 1); lo que llega sin etiqueta va a la nativa del que recibe. Si no coincide, esa VLAN se rompe o se mezcla. Buena práctica: nativa dedicada sin uso (ej. 999), igual en ambos extremos, nunca la VLAN 1.'}},
't33':{id:'t3-3',lv:3,t:'Lee el show: diagnóstico de trunks',
 story:'Son las 7:40 y entra un ticket: "Las cámaras del piso 4 no graban". Lupita no te deja tocar nada: "Primero lee. Un buen ingeniero diagnostica con tres comandos show antes de escribir un solo configure."',
 body:['En el trabajo vas a leer muchos más <code>show</code> de los que vas a configurar. Saber leer la salida rápido es lo que separa al que adivina del que diagnostica. Estas son las tres salidas que más vas a ver con trunks.',
  '<h3>Cisco: <code>show interfaces trunk</code> tiene tres bloques</h3><ol class="pasos"><li><strong>Arriba:</strong> cada trunk con su modo, estado y <strong>Native vlan</strong>. Compara la nativa con la del otro extremo.</li><li><strong>Vlans allowed on trunk:</strong> la lista configurada. Si dice <code>1-4094</code>, nadie lo podó.</li><li><strong>Vlans allowed and active:</strong> las que además <em>existen</em> en ese switch. Si una VLAN está permitida pero no aparece aquí, no la han creado en ese switch.</li></ol>',
  '<h3>Aruba: <code>show interface brief</code></h3>Fíjate en dos columnas: <strong>Mode</strong> (access o trunk) y <strong>Native VLAN</strong>. Para ver la lista de permitidas usa <code>show running-config interface 1/1/24</code> o <code>show vlan</code>, que te dice en qué puertos está cada VLAN.',
  '<h3>Juniper: <code>show ethernet-switching interfaces</code></h3>Cada interfaz lista sus VLAN, una por renglón, con su número (TAG) y la columna <strong>Tagging</strong>: <em>tagged</em> viaja con etiqueta; <em>untagged</em> es la nativa (o la VLAN de un access port).',
  '<h3>El método en 3 preguntas</h3><ol class="pasos"><li>¿El puerto entre switches es <strong>trunk</strong> en los dos lados?</li><li>¿La VLAN que falla está <strong>permitida y activa</strong> en los dos lados?</li><li>¿La <strong>nativa</strong> es la misma en los dos lados?</li></ol>',
  'Juega abajo: diagnostica salidas reales.'],
 fig:'showread',
 real:'<h3>Así lo ves en la vida real</h3><p>En muchas empresas no te dan permiso de configuración el primer mes: te dan acceso de solo lectura y te piden diagnosticar. Si llegas con "el trunk de Gi0/24 en ACC2 no permite la 30, la nativa está bien" en vez de "no sé, no funciona", ya te ganaste el siguiente ticket. En los exámenes de Cisco, Aruba y Juniper también hay preguntas de "lee esta salida".</p>',
 quiz:[{q:'En Cisco, "Vlans allowed on trunk: 1-4094" significa…',o:['Que el trunk no está podado: deja pasar todas','Que el trunk está apagado','Que solo pasa la VLAN 1','Que hay 4094 PCs'],a:0,why:'Es la lista por defecto de Cisco.'},
  {q:'Una VLAN aparece en "Vlans allowed on trunk" pero no en "allowed and active". ¿Qué pasa?',o:['La VLAN no existe en ese switch: hay que crearla','Está cifrada','Es la nativa','Todo está bien'],a:0,why:'Activa = permitida y además creada en ese switch.'},
  {q:'Aruba show interface brief: el uplink dice Mode "access". ¿Qué significa?',o:['No es trunk: solo lleva una VLAN sin etiqueta','Es un trunk podado','Está apagado','Es la nativa'],a:0,why:'Un enlace entre switches con varias VLAN debe ser trunk.'},
  {q:'Juniper: en show ethernet-switching interfaces, NATIVA (999) aparece como "untagged" en ge-0/0/23. ¿Qué significa?',o:['Que la 999 es la nativa de ese trunk','Que está mal configurada','Que no existe','Que es la VLAN de voz'],a:0,why:'En un trunk, la untagged es la nativa.'},
  {q:'Cisco show interfaces trunk en ACC1 dice Native vlan 999 y en CORE dice 30. ¿Qué VLAN se rompe en ese enlace?',o:['La 30, que el CORE manda sin etiqueta','La 999','Ninguna','Todas'],a:0,why:'El CORE manda la 30 sin etiqueta y ACC1 la mete en su nativa, la 999.'},
  {q:'¿Cuál es la primera pregunta del método de 3 pasos?',o:['¿El puerto entre switches es trunk en los dos lados?','¿La PC tiene antivirus?','¿El cable es azul?','¿Hay internet?'],a:0,why:'Sin trunk no hay varias VLAN.'},
  {q:'Aruba: ¿qué columna de show interface brief te dice la nativa de un trunk?',o:['Native VLAN','Speed','Reason','Type'],a:0,why:'La columna Native VLAN.'},
  {q:'¿Qué comando de Cisco usas primero cuando "una VLAN no cruza al otro piso"?',o:['show interfaces trunk','show clock','show version','ping 8.8.8.8'],a:0,why:'Te da modo, nativa, permitidas y activas de cada trunk.'},
  {q:'En la tabla de un trunk ves la VLAN 150 (SERVIDORES) permitida hacia un switch de acceso que no la usa. ¿Qué haces?',o:['La quito de la lista de permitidas (podar)','Nada, no importa','Borro la VLAN 150 del core','Apago el trunk'],a:0,why:'No debe salir del core: se poda.'},
  {q:'¿Por qué se diagnostica con show antes de configurar?',o:['Para entender el problema y no romper algo que funcionaba','Porque configure está prohibido','Porque es más rápido escribir','No se hace así'],a:0,why:'Primero se entiende, después se cambia.'}],
 exp:{q:'Con tus palabras: si una VLAN no cruza un trunk, ¿qué tres cosas revisas, con qué comando en tu vendor favorito y qué buscas en la salida?',
  ideas:['Que el puerto sea trunk en los dos extremos','Que la VLAN esté permitida y activa (creada) en los dos extremos','Que la nativa sea la misma en los dos extremos','Un comando show concreto y la columna o bloque que miras'],
  short:['¿es trunk?','permitida y activa','la nativa','el comando y qué miras'],
  kw:[['trunk','modo','mode'],['permitid','allowed','activ','existe','creada'],['nativa','native','untagged'],['show interfaces trunk','show interface brief','ethernet-switching','show vlan','columna']],
  fix:['Primero confirmo que el puerto entre switches es trunk en los dos lados.','Luego reviso que la VLAN esté permitida y activa (creada) en los dos extremos.','Después comparo la VLAN nativa en los dos extremos: debe ser la misma.','Lo veo con un show, por ejemplo show interfaces trunk en Cisco: columna Native vlan y los bloques de permitidas y activas.'],
  mine:'Si una VLAN no cruza, primero veo que el puerto entre switches sea trunk de los dos lados, porque si uno está en access solo pasa una VLAN. Después reviso que esa VLAN esté permitida y además activa, o sea creada, en los dos extremos. Y al final comparo la nativa de los dos lados, porque si no coincide la VLAN que va sin etiqueta se pierde. En Cisco lo hago con show interfaces trunk: arriba veo el modo y la Native vlan, en medio la lista de permitidas y abajo las activas.',
  model:'Reviso: 1) que sea trunk en ambos lados, 2) que la VLAN esté permitida y activa en ambos, 3) que la nativa coincida. Cisco: show interfaces trunk (Native vlan, allowed, allowed and active). Aruba: show interface brief. Juniper: show ethernet-switching interfaces.'}}
});
Object.assign(VOCAB,{
 't31':[['Trunk','enlace que lleva varias VLAN'],['802.1Q','estándar de la etiqueta de VLAN'],['Tag / tagged','etiqueta / con etiqueta'],['Untagged','sin etiqueta'],['VLAN ID (VID)','número de VLAN, 12 bits'],['Allowed VLANs','VLAN permitidas en el trunk'],['Pruning','podar: quitar VLAN del trunk'],['Uplink','enlace hacia el core']],
 't32':[['Native VLAN','VLAN nativa: viaja sin etiqueta'],['Native VLAN mismatch','la nativa no coincide'],['CDP','protocolo de vecinos de Cisco'],['LLDP','protocolo de vecinos estándar'],['VLAN hopping','ataque para saltar a otra VLAN'],['Double tagging','doble etiqueta, técnica de ataque'],['Blackhole VLAN','VLAN vacía a propósito'],['native-vlan-id','la nativa en Juniper']],
 't33':[['show interfaces trunk','resumen de trunks en Cisco'],['allowed and active','permitidas y creadas'],['show interface brief','resumen de puertos en Aruba'],['show ethernet-switching interfaces','puertos de capa 2 en Juniper'],['Tagging','tagged o untagged'],['Troubleshooting','diagnóstico'],['Read-only access','acceso de solo lectura'],['Root cause','causa raíz']],
 'lab3':[['switchport trunk allowed vlan','lista de permitidas (Cisco)'],['vlan trunk allowed','agrega a la lista (Aruba)'],['no vlan trunk allowed','quita de la lista (Aruba)'],['switchport trunk native vlan','nativa (Cisco)'],['vlan trunk native','nativa (Aruba)'],['native-vlan-id','nativa (Juniper)'],['vlan members','VLAN del puerto (Juniper)'],['show interfaces trunk','revisar trunks (Cisco)']]
});
Object.assign(ALT,{
 't3-1':{fig:'Vuelve al simulador del trunk y manda un frame de cada VLAN antes y después de podar.',analog:'El trunk es un autobús que lleva pasajeros de varias empresas. Cada pasajero trae un gafete con el nombre de su empresa (la etiqueta). Al llegar, el guardia lee el gafete, se lo quita y lo manda al piso de su empresa. La lista de permitidas es la lista del guardia: si tu empresa no está, no subes.',guide:['¿Qué le agrega 802.1Q al frame?','¿Qué hace el switch que lo recibe?','¿Qué VLAN lleva un trunk de Cisco por defecto?','¿Por qué se poda?']},
 't3-2':{fig:'Vuelve al simulador y pon la nativa 10 solo de un lado: mira qué pasa con la VLAN 10.',analog:'En el autobús todos traen gafete menos los de una empresa, que entran "de casa". Si en una terminal "los de casa" son de Ventas y en la otra son de RRHH, los de Ventas que llegan sin gafete terminan en el piso de RRHH. Por eso las dos terminales deben estar de acuerdo, y mejor que "los de casa" sean de una empresa vacía.',guide:['¿Qué tiene de especial la VLAN nativa?','¿Qué hace el switch con lo que llega sin etiqueta?','¿Qué pasa si no coincide?','¿Cuál es la buena práctica?']},
 't3-3':{fig:'Vuelve al juego de salidas y antes de responder aplica las 3 preguntas: ¿trunk? ¿permitida y activa? ¿nativa igual?',analog:'Es como revisar un coche que no arranca: primero ves si tiene gasolina, luego la batería, luego la marcha. Siempre en el mismo orden, sin desarmar nada antes de mirar.',guide:['¿Cuál es la primera pregunta?','¿Qué diferencia hay entre permitida y activa?','¿Dónde ves la nativa en tu vendor?','¿Con qué comando empiezas?']}
});
